-- Northwind AcaciaDB UI object definitions

-- Import data/northwind_normalized.sql first, then import this file.

USE `northwind`;

CREATE TABLE IF NOT EXISTS `acaciadb_object_definitions` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `object_type` ENUM('form','query','report','table') NOT NULL,
  `object_name` VARCHAR(120) NOT NULL,
  `definition_json` JSON NOT NULL,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `object_unique` (`object_type`, `object_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `acaciadb_object_definitions` (`object_type`, `object_name`, `definition_json`) VALUES ('form', 'Customers Form', '{"title":"Customers","parentTable":"customers","parentKey":"id","fields":["id","company","last_name","first_name","e-mail_address","job_title","business_phone","home_phone","mobile_phone","fax_number","address","city","state/province","zip/postal_code","country/region","web_page","notes","attachments"],"subform":{"title":"Orders Subform","table":"orders","foreignKey":"customer_id","columns":["order_id","order_date","status_id","employee_id","shipping_fee"]}}')
ON DUPLICATE KEY UPDATE `definition_json` = VALUES(`definition_json`), `updated_at` = CURRENT_TIMESTAMP;

