INSERT INTO `acaciadb_object_definitions` (`object_type`, `object_name`, `definition_json`) VALUES ('query', 'Customer Orders Linked', '{"title":"Customer Orders Linked","tables":["customers","orders","employees","shippers","orders_status","orders_tax_status"],"connections":[{"from":"customers.id","to":"orders.customer_id"},{"from":"employees.id","to":"orders.employee_id"},{"from":"shippers.id","to":"orders.shipper_id"},{"from":"orders_status.status_id","to":"orders.status_id"},{"from":"orders_tax_status.id","to":"orders.tax_status"}],"fields":[{"field":"id","table":"customers","sort":"","show":true,"criteria":""},{"field":"company","table":"customers","sort":"Ascending","show":true,"criteria":""},{"field":"order_id","table":"orders","sort":"","show":true,"criteria":""},{"field":"order_date","table":"orders","sort":"Descending","show":true,"criteria":""},{"field":"status_name","table":"orders_status","sort":"","show":true,"criteria":""},{"field":"last_name","table":"employees","sort":"","show":true,"criteria":""},{"field":"company","table":"shippers","sort":"","show":true,"criteria":""},{"field":"tax_status_name","table":"orders_tax_status","sort":"","show":true,"criteria":""}],"sql":"SELECT c.id AS customer_id, c.company AS customer_company, o.order_id, o.order_date, os.status_name AS order_status, CONCAT_WS(\" \", e.first_name, e.last_name) AS employee_name, s.company AS shipper_company, ots.tax_status_name FROM customers c LEFT JOIN orders o ON o.customer_id = c.id LEFT JOIN employees e ON e.id = o.employee_id LEFT JOIN shippers s ON s.id = o.shipper_id LEFT JOIN orders_status os ON os.status_id = o.status_id LEFT JOIN orders_tax_status ots ON ots.id = o.tax_status ORDER BY c.company, o.order_date DESC;"}')
ON DUPLICATE KEY UPDATE `definition_json` = VALUES(`definition_json`), `updated_at` = CURRENT_TIMESTAMP;

INSERT INTO `acaciadb_object_definitions` (`object_type`, `object_name`, `definition_json`) VALUES ('query', 'Order Line Items Linked', '{"title":"Order Line Items Linked","tables":["orders","order_details","products","order_details_status"],"connections":[{"from":"orders.order_id","to":"order_details.order_id"},{"from":"products.id","to":"order_details.product_id"},{"from":"order_details_status.status_id","to":"order_details.status_id"}],"fields":[{"field":"order_id","table":"orders","sort":"Descending","show":true,"criteria":""},{"field":"id","table":"order_details","sort":"","show":true,"criteria":""},{"field":"product_name","table":"products","sort":"Ascending","show":true,"criteria":""},{"field":"quantity","table":"order_details","sort":"","show":true,"criteria":""},{"field":"unit_price","table":"order_details","sort":"","show":true,"criteria":""},{"field":"discount","table":"order_details","sort":"","show":true,"criteria":""},{"field":"status_name","table":"order_details_status","sort":"","show":true,"criteria":""}],"sql":"SELECT o.order_id, od.id AS line_id, p.product_name, od.quantity, od.unit_price, od.discount, ods.status_name AS line_status FROM orders o INNER JOIN order_details od ON od.order_id = o.order_id LEFT JOIN products p ON p.id = od.product_id LEFT JOIN order_details_status ods ON ods.status_id = od.status_id ORDER BY o.order_id DESC, od.id;"}')
ON DUPLICATE KEY UPDATE `definition_json` = VALUES(`definition_json`), `updated_at` = CURRENT_TIMESTAMP;

INSERT INTO `acaciadb_object_definitions` (`object_type`, `object_name`, `definition_json`) VALUES ('query', 'Order Invoices Linked', '{"title":"Order Invoices Linked","tables":["customers","orders","invoices"],"connections":[{"from":"customers.id","to":"orders.customer_id"},{"from":"orders.order_id","to":"invoices.order_id"}],"fields":[{"field":"invoice_id","table":"invoices","sort":"Descending","show":true,"criteria":""},{"field":"order_id","table":"orders","sort":"","show":true,"criteria":""},{"field":"company","table":"customers","sort":"Ascending","show":true,"criteria":""},{"field":"invoice_date","table":"invoices","sort":"","show":true,"criteria":""},{"field":"due_date","table":"invoices","sort":"","show":true,"criteria":""},{"field":"amount_due","table":"invoices","sort":"","show":true,"criteria":""}],"sql":"SELECT i.invoice_id, o.order_id, c.company AS customer_company, i.invoice_date, i.due_date, i.amount_due FROM invoices i INNER JOIN orders o ON o.order_id = i.order_id LEFT JOIN customers c ON c.id = o.customer_id ORDER BY i.invoice_date DESC, i.invoice_id DESC;"}')
ON DUPLICATE KEY UPDATE `definition_json` = VALUES(`definition_json`), `updated_at` = CURRENT_TIMESTAMP;

INSERT INTO `acaciadb_object_definitions` (`object_type`, `object_name`, `definition_json`) VALUES ('query', 'Inventory Transactions Linked', '{"title":"Inventory Transactions Linked","tables":["inventory_transactions","inventory_transaction_types","products","purchase_orders","orders"],"connections":[{"from":"inventory_transaction_types.id","to":"inventory_transactions.transaction_type"},{"from":"products.id","to":"inventory_transactions.product_id"},{"from":"purchase_orders.purchase_order_id","to":"inventory_transactions.purchase_order_id"},{"from":"orders.order_id","to":"inventory_transactions.customer_order_id"}],"fields":[{"field":"transaction_id","table":"inventory_transactions","sort":"Descending","show":true,"criteria":""},{"field":"type_name","table":"inventory_transaction_types","sort":"","show":true,"criteria":""},{"field":"product_name","table":"products","sort":"Ascending","show":true,"criteria":""},{"field":"quantity","table":"inventory_transactions","sort":"","show":true,"criteria":""},{"field":"purchase_order_id","table":"inventory_transactions","sort":"","show":true,"criteria":""},{"field":"customer_order_id","table":"inventory_transactions","sort":"","show":true,"criteria":""},{"field":"transaction_created_date","table":"inventory_transactions","sort":"","show":true,"criteria":""}],"sql":"SELECT it.transaction_id, itt.type_name, p.product_name, it.quantity, it.purchase_order_id, it.customer_order_id, it.transaction_created_date FROM inventory_transactions it INNER JOIN inventory_transaction_types itt ON itt.id = it.transaction_type LEFT JOIN products p ON p.id = it.product_id LEFT JOIN purchase_orders po ON po.purchase_order_id = it.purchase_order_id LEFT JOIN orders o ON o.order_id = it.customer_order_id ORDER BY it.transaction_id DESC;"}')
ON DUPLICATE KEY UPDATE `definition_json` = VALUES(`definition_json`), `updated_at` = CURRENT_TIMESTAMP;

INSERT INTO `acaciadb_object_definitions` (`object_type`, `object_name`, `definition_json`) VALUES ('query', 'Purchase Orders Linked', '{"title":"Purchase Orders Linked","tables":["purchase_orders","suppliers","employees","purchase_order_status"],"connections":[{"from":"suppliers.id","to":"purchase_orders.supplier_id"},{"from":"employees.id","to":"purchase_orders.created_by"},{"from":"purchase_order_status.status_id","to":"purchase_orders.status_id"}],"fields":[{"field":"purchase_order_id","table":"purchase_orders","sort":"Descending","show":true,"criteria":""},{"field":"company","table":"suppliers","sort":"Ascending","show":true,"criteria":""},{"field":"last_name","table":"employees","sort":"","show":true,"criteria":""},{"field":"status","table":"purchase_order_status","sort":"","show":true,"criteria":""},{"field":"submitted_date","table":"purchase_orders","sort":"","show":true,"criteria":""},{"field":"expected_date","table":"purchase_orders","sort":"","show":true,"criteria":""},{"field":"payment_amount","table":"purchase_orders","sort":"","show":true,"criteria":""}],"sql":"SELECT po.purchase_order_id, s.company AS supplier_company, CONCAT_WS(\" \", e.first_name, e.last_name) AS created_by_name, pos.status AS purchase_status, po.submitted_date, po.expected_date, po.payment_amount FROM purchase_orders po LEFT JOIN suppliers s ON s.id = po.supplier_id LEFT JOIN employees e ON e.id = po.created_by LEFT JOIN purchase_order_status pos ON pos.status_id = po.status_id ORDER BY po.purchase_order_id DESC;"}')
ON DUPLICATE KEY UPDATE `definition_json` = VALUES(`definition_json`), `updated_at` = CURRENT_TIMESTAMP;

INSERT INTO `acaciadb_object_definitions` (`object_type`, `object_name`, `definition_json`) VALUES ('query', 'Purchase Order Details Linked', '{"title":"Purchase Order Details Linked","tables":["purchase_order_details","purchase_orders","products","inventory_transactions"],"connections":[{"from":"purchase_orders.purchase_order_id","to":"purchase_order_details.purchase_order_id"},{"from":"products.id","to":"purchase_order_details.product_id"},{"from":"inventory_transactions.transaction_id","to":"purchase_order_details.inventory_id"}],"fields":[{"field":"id","table":"purchase_order_details","sort":"Descending","show":true,"criteria":""},{"field":"purchase_order_id","table":"purchase_orders","sort":"","show":true,"criteria":""},{"field":"product_name","table":"products","sort":"Ascending","show":true,"criteria":""},{"field":"quantity","table":"purchase_order_details","sort":"","show":true,"criteria":""},{"field":"unit_cost","table":"purchase_order_details","sort":"","show":true,"criteria":""},{"field":"date_received","table":"purchase_order_details","sort":"","show":true,"criteria":""},{"field":"inventory_id","table":"purchase_order_details","sort":"","show":true,"criteria":""}],"sql":"SELECT pod.id AS detail_id, po.purchase_order_id, p.product_name, pod.quantity, pod.unit_cost, pod.date_received, pod.inventory_id FROM purchase_order_details pod INNER JOIN purchase_orders po ON po.purchase_order_id = pod.purchase_order_id LEFT JOIN products p ON p.id = pod.product_id LEFT JOIN inventory_transactions it ON it.transaction_id = pod.inventory_id ORDER BY pod.id DESC;"}')
ON DUPLICATE KEY UPDATE `definition_json` = VALUES(`definition_json`), `updated_at` = CURRENT_TIMESTAMP;

INSERT INTO `acaciadb_object_definitions` (`object_type`, `object_name`, `definition_json`) VALUES ('query', 'Employee Privileges Linked', '{"title":"Employee Privileges Linked","tables":["employees","employee_privileges","privileges"],"connections":[{"from":"employees.id","to":"employee_privileges.employee_id"},{"from":"privileges.privilege_id","to":"employee_privileges.privilege_id"}],"fields":[{"field":"id","table":"employees","sort":"","show":true,"criteria":""},{"field":"last_name","table":"employees","sort":"Ascending","show":true,"criteria":""},{"field":"first_name","table":"employees","sort":"Ascending","show":true,"criteria":""},{"field":"privilege_name","table":"privileges","sort":"Ascending","show":true,"criteria":""}],"sql":"SELECT e.id AS employee_id, CONCAT_WS(\" \", e.first_name, e.last_name) AS employee_name, p.privilege_name FROM employees e INNER JOIN employee_privileges ep ON ep.employee_id = e.id INNER JOIN privileges p ON p.privilege_id = ep.privilege_id ORDER BY e.last_name, e.first_name, p.privilege_name;"}')
ON DUPLICATE KEY UPDATE `definition_json` = VALUES(`definition_json`), `updated_at` = CURRENT_TIMESTAMP;

INSERT INTO `acaciadb_object_definitions` (`object_type`, `object_name`, `definition_json`) SELECT 'report', 'Customer Orders Linked Report', JSON_OBJECT('title', 'Customer Orders Linked Report', 'period', 'Snapshot generated during northwind_ui.sql import', 'sourceQuery', 'Customer Orders Linked', 'columns', JSON_ARRAY('Customer ID', 'Customer', 'Order ID', 'Order Date', 'Status', 'Employee', 'Shipper', 'Tax Status'), 'rows', (SELECT COALESCE(JSON_ARRAYAGG(JSON_OBJECT('Customer ID', `report_rows`.`customer_id`, 'Customer', `report_rows`.`customer`, 'Order ID', `report_rows`.`order_id`, 'Order Date', `report_rows`.`order_date`, 'Status', `report_rows`.`status`, 'Employee', `report_rows`.`employee`, 'Shipper', `report_rows`.`shipper`, 'Tax Status', `report_rows`.`tax_status`)), JSON_ARRAY()) FROM (SELECT c.id AS customer_id, c.company AS customer, o.order_id, o.order_date, os.status_name AS status, CONCAT_WS(" ", e.first_name, e.last_name) AS employee, s.company AS shipper, ots.tax_status_name AS tax_status FROM customers c LEFT JOIN orders o ON o.customer_id = c.id LEFT JOIN employees e ON e.id = o.employee_id LEFT JOIN shippers s ON s.id = o.shipper_id LEFT JOIN orders_status os ON os.status_id = o.status_id LEFT JOIN orders_tax_status ots ON ots.id = o.tax_status ORDER BY c.company, o.order_date DESC LIMIT 500) AS `report_rows`), 'stats', JSON_ARRAY(), 'chart', JSON_ARRAY())
ON DUPLICATE KEY UPDATE `definition_json` = VALUES(`definition_json`), `updated_at` = CURRENT_TIMESTAMP;

INSERT INTO `acaciadb_object_definitions` (`object_type`, `object_name`, `definition_json`) SELECT 'report', 'Order Line Items Linked Report', JSON_OBJECT('title', 'Order Line Items Linked Report', 'period', 'Snapshot generated during northwind_ui.sql import', 'sourceQuery', 'Order Line Items Linked', 'columns', JSON_ARRAY('Order ID', 'Line ID', 'Product', 'Quantity', 'Unit Price', 'Discount', 'Status'), 'rows', (SELECT COALESCE(JSON_ARRAYAGG(JSON_OBJECT('Order ID', `report_rows`.`order_id`, 'Line ID', `report_rows`.`line_id`, 'Product', `report_rows`.`product`, 'Quantity', `report_rows`.`quantity`, 'Unit Price', `report_rows`.`unit_price`, 'Discount', `report_rows`.`discount`, 'Status', `report_rows`.`status`)), JSON_ARRAY()) FROM (SELECT o.order_id, od.id AS line_id, p.product_name AS product, od.quantity, od.unit_price, od.discount, ods.status_name AS status FROM orders o INNER JOIN order_details od ON od.order_id = o.order_id LEFT JOIN products p ON p.id = od.product_id LEFT JOIN order_details_status ods ON ods.status_id = od.status_id ORDER BY o.order_id DESC, od.id LIMIT 500) AS `report_rows`), 'stats', JSON_ARRAY(), 'chart', JSON_ARRAY())
ON DUPLICATE KEY UPDATE `definition_json` = VALUES(`definition_json`), `updated_at` = CURRENT_TIMESTAMP;

INSERT INTO `acaciadb_object_definitions` (`object_type`, `object_name`, `definition_json`) SELECT 'report', 'Order Invoices Linked Report', JSON_OBJECT('title', 'Order Invoices Linked Report', 'period', 'Snapshot generated during northwind_ui.sql import', 'sourceQuery', 'Order Invoices Linked', 'columns', JSON_ARRAY('Invoice ID', 'Order ID', 'Customer', 'Invoice Date', 'Due Date', 'Amount Due'), 'rows', (SELECT COALESCE(JSON_ARRAYAGG(JSON_OBJECT('Invoice ID', `report_rows`.`invoice_id`, 'Order ID', `report_rows`.`order_id`, 'Customer', `report_rows`.`customer`, 'Invoice Date', `report_rows`.`invoice_date`, 'Due Date', `report_rows`.`due_date`, 'Amount Due', `report_rows`.`amount_due`)), JSON_ARRAY()) FROM (SELECT i.invoice_id, o.order_id, c.company AS customer, i.invoice_date, i.due_date, i.amount_due FROM invoices i INNER JOIN orders o ON o.order_id = i.order_id LEFT JOIN customers c ON c.id = o.customer_id ORDER BY i.invoice_date DESC, i.invoice_id DESC LIMIT 500) AS `report_rows`), 'stats', JSON_ARRAY(), 'chart', JSON_ARRAY())
ON DUPLICATE KEY UPDATE `definition_json` = VALUES(`definition_json`), `updated_at` = CURRENT_TIMESTAMP;

INSERT INTO `acaciadb_object_definitions` (`object_type`, `object_name`, `definition_json`) SELECT 'report', 'Inventory Transactions Linked Report', JSON_OBJECT('title', 'Inventory Transactions Linked Report', 'period', 'Snapshot generated during northwind_ui.sql import', 'sourceQuery', 'Inventory Transactions Linked', 'columns', JSON_ARRAY('Transaction ID', 'Type', 'Product', 'Quantity', 'Purchase Order ID', 'Customer Order ID', 'Created'), 'rows', (SELECT COALESCE(JSON_ARRAYAGG(JSON_OBJECT('Transaction ID', `report_rows`.`transaction_id`, 'Type', `report_rows`.`type`, 'Product', `report_rows`.`product`, 'Quantity', `report_rows`.`quantity`, 'Purchase Order ID', `report_rows`.`purchase_order_id`, 'Customer Order ID', `report_rows`.`customer_order_id`, 'Created', `report_rows`.`created`)), JSON_ARRAY()) FROM (SELECT it.transaction_id, itt.type_name AS type, p.product_name AS product, it.quantity, it.purchase_order_id, it.customer_order_id, it.transaction_created_date AS created FROM inventory_transactions it INNER JOIN inventory_transaction_types itt ON itt.id = it.transaction_type LEFT JOIN products p ON p.id = it.product_id LEFT JOIN purchase_orders po ON po.purchase_order_id = it.purchase_order_id LEFT JOIN orders o ON o.order_id = it.customer_order_id ORDER BY it.transaction_id DESC LIMIT 500) AS `report_rows`), 'stats', JSON_ARRAY(), 'chart', JSON_ARRAY())
ON DUPLICATE KEY UPDATE `definition_json` = VALUES(`definition_json`), `updated_at` = CURRENT_TIMESTAMP;

INSERT INTO `acaciadb_object_definitions` (`object_type`, `object_name`, `definition_json`) SELECT 'report', 'Purchase Orders Linked Report', JSON_OBJECT('title', 'Purchase Orders Linked Report', 'period', 'Snapshot generated during northwind_ui.sql import', 'sourceQuery', 'Purchase Orders Linked', 'columns', JSON_ARRAY('Purchase Order ID', 'Supplier', 'Created By', 'Status', 'Submitted', 'Expected', 'Payment Amount'), 'rows', (SELECT COALESCE(JSON_ARRAYAGG(JSON_OBJECT('Purchase Order ID', `report_rows`.`purchase_order_id`, 'Supplier', `report_rows`.`supplier`, 'Created By', `report_rows`.`created_by`, 'Status', `report_rows`.`status`, 'Submitted', `report_rows`.`submitted`, 'Expected', `report_rows`.`expected`, 'Payment Amount', `report_rows`.`payment_amount`)), JSON_ARRAY()) FROM (SELECT po.purchase_order_id, s.company AS supplier, CONCAT_WS(" ", e.first_name, e.last_name) AS created_by, pos.status, po.submitted_date AS submitted, po.expected_date AS expected, po.payment_amount FROM purchase_orders po LEFT JOIN suppliers s ON s.id = po.supplier_id LEFT JOIN employees e ON e.id = po.created_by LEFT JOIN purchase_order_status pos ON pos.status_id = po.status_id ORDER BY po.purchase_order_id DESC LIMIT 500) AS `report_rows`), 'stats', JSON_ARRAY(), 'chart', JSON_ARRAY())
ON DUPLICATE KEY UPDATE `definition_json` = VALUES(`definition_json`), `updated_at` = CURRENT_TIMESTAMP;

INSERT INTO `acaciadb_object_definitions` (`object_type`, `object_name`, `definition_json`) SELECT 'report', 'Purchase Order Details Linked Report', JSON_OBJECT('title', 'Purchase Order Details Linked Report', 'period', 'Snapshot generated during northwind_ui.sql import', 'sourceQuery', 'Purchase Order Details Linked', 'columns', JSON_ARRAY('Detail ID', 'Purchase Order ID', 'Product', 'Quantity', 'Unit Cost', 'Date Received', 'Inventory ID'), 'rows', (SELECT COALESCE(JSON_ARRAYAGG(JSON_OBJECT('Detail ID', `report_rows`.`detail_id`, 'Purchase Order ID', `report_rows`.`purchase_order_id`, 'Product', `report_rows`.`product`, 'Quantity', `report_rows`.`quantity`, 'Unit Cost', `report_rows`.`unit_cost`, 'Date Received', `report_rows`.`date_received`, 'Inventory ID', `report_rows`.`inventory_id`)), JSON_ARRAY()) FROM (SELECT pod.id AS detail_id, po.purchase_order_id, p.product_name AS product, pod.quantity, pod.unit_cost, pod.date_received, pod.inventory_id FROM purchase_order_details pod INNER JOIN purchase_orders po ON po.purchase_order_id = pod.purchase_order_id LEFT JOIN products p ON p.id = pod.product_id LEFT JOIN inventory_transactions it ON it.transaction_id = pod.inventory_id ORDER BY pod.id DESC LIMIT 500) AS `report_rows`), 'stats', JSON_ARRAY(), 'chart', JSON_ARRAY())
ON DUPLICATE KEY UPDATE `definition_json` = VALUES(`definition_json`), `updated_at` = CURRENT_TIMESTAMP;

INSERT INTO `acaciadb_object_definitions` (`object_type`, `object_name`, `definition_json`) SELECT 'report', 'Employee Privileges Linked Report', JSON_OBJECT('title', 'Employee Privileges Linked Report', 'period', 'Snapshot generated during northwind_ui.sql import', 'sourceQuery', 'Employee Privileges Linked', 'columns', JSON_ARRAY('Employee ID', 'Employee', 'Privilege'), 'rows', (SELECT COALESCE(JSON_ARRAYAGG(JSON_OBJECT('Employee ID', `report_rows`.`employee_id`, 'Employee', `report_rows`.`employee`, 'Privilege', `report_rows`.`privilege`)), JSON_ARRAY()) FROM (SELECT e.id AS employee_id, CONCAT_WS(" ", e.first_name, e.last_name) AS employee, p.privilege_name AS privilege FROM employees e INNER JOIN employee_privileges ep ON ep.employee_id = e.id INNER JOIN privileges p ON p.privilege_id = ep.privilege_id ORDER BY e.last_name, e.first_name, p.privilege_name LIMIT 500) AS `report_rows`), 'stats', JSON_ARRAY(), 'chart', JSON_ARRAY())
ON DUPLICATE KEY UPDATE `definition_json` = VALUES(`definition_json`), `updated_at` = CURRENT_TIMESTAMP;

SELECT `object_type`, COUNT(*) AS `object_count` FROM `acaciadb_object_definitions` GROUP BY `object_type` ORDER BY `object_type`;
